17	package org.apache.kafka.clients.consumer.internals;
18	
19	import org.apache.kafka.clients.ClientResponse;
20	import org.apache.kafka.clients.FetchSessionHandler;
21	import org.apache.kafka.common.Cluster;
22	import org.apache.kafka.common.Node;
23	import org.apache.kafka.common.TopicPartition;
24	import org.apache.kafka.common.Uuid;
25	import org.apache.kafka.common.internals.IdempotentCloser;
26	import org.apache.kafka.common.message.FetchResponseData;
27	import org.apache.kafka.common.protocol.ApiKeys;
28	import org.apache.kafka.common.protocol.Errors;
29	import org.apache.kafka.common.requests.FetchRequest;
30	import org.apache.kafka.common.requests.FetchResponse;
31	import org.apache.kafka.common.utils.BufferSupplier;
32	import org.apache.kafka.common.utils.LogContext;
33	import org.apache.kafka.common.utils.Time;
34	import org.apache.kafka.common.utils.Timer;
35	import org.apache.kafka.common.utils.Utils;
36	import org.slf4j.Logger;
37	import org.slf4j.helpers.MessageFormatter;
38	
39	import java.io.Closeable;
40	import java.util.ArrayList;
41	import java.util.HashMap;
42	import java.util.HashSet;
43	import java.util.LinkedHashMap;
44	import java.util.List;
45	import java.util.Map;
46	import java.util.Optional;
47	import java.util.Set;
48	import java.util.function.Predicate;
49	
50	import static org.apache.kafka.clients.consumer.internals.FetchUtils.requestMetadataUpdate;
51	
52	/**
53	 * {@code AbstractFetch} represents the basic state and logic for record fetching processing.
54	 * @param <K> Type for the message key
55	 * @param <V> Type for the message value
56	 */
57	public abstract class AbstractFetch<K, V> implements Closeable {
58	
59	    private final Logger log;
60	    protected final LogContext logContext;
61	    protected final ConsumerNetworkClient client;
62	    protected final ConsumerMetadata metadata;
63	    protected final SubscriptionState subscriptions;
64	    protected final FetchConfig<K, V> fetchConfig;
65	    protected final Time time;
66	    protected final FetchMetricsManager metricsManager;
67	    protected final FetchBuffer fetchBuffer;
68	    protected final BufferSupplier decompressionBufferSupplier;
69	    protected final Set<Integer> nodesWithPendingFetchRequests;
70	    protected final IdempotentCloser idempotentCloser = new IdempotentCloser();
71	
72	    private final Map<Integer, FetchSessionHandler> sessionHandlers;
73	
74	    public AbstractFetch(final LogContext logContext,
75	                         final ConsumerNetworkClient client,
76	                         final ConsumerMetadata metadata,
77	                         final SubscriptionState subscriptions,
78	                         final FetchConfig<K, V> fetchConfig,
79	                         final FetchMetricsManager metricsManager,
80	                         final Time time) {
81	        this.log = logContext.logger(AbstractFetch.class);
82	        this.logContext = logContext;
83	        this.client = client;
84	        this.metadata = metadata;
85	        this.subscriptions = subscriptions;
86	        this.fetchConfig = fetchConfig;
87	        this.decompressionBufferSupplier = BufferSupplier.create();
88	        this.fetchBuffer = new FetchBuffer(logContext);
89	        this.sessionHandlers = new HashMap<>();
90	        this.nodesWithPendingFetchRequests = new HashSet<>();
91	        this.metricsManager = metricsManager;
92	        this.time = time;
93	    }
94	
95	    /**
96	     * Return whether we have any completed fetches pending return to the user. This method is thread-safe. Has
97	     * visibility for testing.
98	     *
99	     * @return true if there are completed fetches, false otherwise
100	     */
101	    boolean hasCompletedFetches() {
102	        return !fetchBuffer.isEmpty();
103	    }
104	
105	    /**
106	     * Return whether we have any completed fetches that are fetchable. This method is thread-safe.
107	     * @return true if there are completed fetches that can be returned, false otherwise
108	     */
109	    public boolean hasAvailableFetches() {
110	        return fetchBuffer.hasCompletedFetches(fetch -> subscriptions.isFetchable(fetch.partition));
111	    }
112	
113	    /**
114	     * Implements the core logic for a successful fetch request/response.
115	     *
116	     * @param fetchTarget {@link Node} from which the fetch data was requested
117	     * @param data {@link FetchSessionHandler.FetchRequestData} that represents the session data
118	     * @param resp {@link ClientResponse} from which the {@link FetchResponse} will be retrieved
119	     */
120	    protected void handleFetchResponse(final Node fetchTarget,
121	                                       final FetchSessionHandler.FetchRequestData data,
122	                                       final ClientResponse resp) {
123	        try {
124	            final FetchResponse response = (FetchResponse) resp.responseBody();
125	            final FetchSessionHandler handler = sessionHandler(fetchTarget.id());
126	
127	            if (handler == null) {
128	                log.error("Unable to find FetchSessionHandler for node {}. Ignoring fetch response.",
129	                        fetchTarget.id());
130	                return;
131	            }
132	
133	            final short requestVersion = resp.requestHeader().apiVersion();
134	
135	            if (!handler.handleResponse(response, requestVersion)) {
136	                if (response.error() == Errors.FETCH_SESSION_TOPIC_ID_ERROR) {
137	                    metadata.requestUpdate(false);
138	                }
139	
140	                return;
141	            }
142	
143	            final Map<TopicPartition, FetchResponseData.PartitionData> responseData = response.responseData(handler.sessionTopicNames(), requestVersion);
144	            final Set<TopicPartition> partitions = new HashSet<>(responseData.keySet());
145	            final FetchMetricsAggregator metricAggregator = new FetchMetricsAggregator(metricsManager, partitions);
146	
147	            for (Map.Entry<TopicPartition, FetchResponseData.PartitionData> entry : responseData.entrySet()) {
148	                TopicPartition partition = entry.getKey();
149	                FetchRequest.PartitionData requestData = data.sessionPartitions().get(partition);
150	
151	                if (requestData == null) {
152	                    String message;
153	
154	                    if (data.metadata().isFull()) {
155	                        message = MessageFormatter.arrayFormat(
156	                                "Response for missing full request partition: partition={}; metadata={}",
157	                                new Object[]{partition, data.metadata()}).getMessage();
158	                    } else {
159	                        message = MessageFormatter.arrayFormat(
160	                                "Response for missing session request partition: partition={}; metadata={}; toSend={}; toForget={}; toReplace={}",
161	                                new Object[]{partition, data.metadata(), data.toSend(), data.toForget(), data.toReplace()}).getMessage();
162	                    }
163	
164	                    // Received fetch response for missing session partition
165	                    throw new IllegalStateException(message);
166	                }
167	
168	                long fetchOffset = requestData.fetchOffset;
169	                FetchResponseData.PartitionData partitionData = entry.getValue();
170	
171	                log.debug("Fetch {} at offset {} for partition {} returned fetch data {}",
172	                        fetchConfig.isolationLevel, fetchOffset, partition, partitionData);
173	
174	                CompletedFetch completedFetch = new CompletedFetch(
175	                        logContext,
176	                        subscriptions,
177	                        decompressionBufferSupplier,
178	                        partition,
179	                        partitionData,
180	                        metricAggregator,
181	                        fetchOffset,
182	                        requestVersion);
183	                fetchBuffer.add(completedFetch);
184	            }
185	
186	            metricsManager.recordLatency(resp.requestLatencyMs());
187	        } finally {
188	            log.debug("Removing pending request for node {}", fetchTarget);
189	            nodesWithPendingFetchRequests.remove(fetchTarget.id());
190	        }
191	    }
192	
193	    /**
194	     * Implements the core logic for a failed fetch request/response.
195	     *
196	     * @param fetchTarget {@link Node} from which the fetch data was requested
197	     * @param t {@link Throwable} representing the error that resulted in the failure
198	     */
199	    protected void handleFetchResponse(final Node fetchTarget, final Throwable t) {
200	        try {
201	            final FetchSessionHandler handler = sessionHandler(fetchTarget.id());
202	
203	            if (handler != null) {
204	                handler.handleError(t);
205	                handler.sessionTopicPartitions().forEach(subscriptions::clearPreferredReadReplica);
206	            }
207	        } finally {
208	            log.debug("Removing pending request for node {}", fetchTarget);
209	            nodesWithPendingFetchRequests.remove(fetchTarget.id());
210	        }
211	    }
212	
213	    protected void handleCloseFetchSessionResponse(final Node fetchTarget,
214	                                                   final FetchSessionHandler.FetchRequestData data) {
215	        int sessionId = data.metadata().sessionId();
216	        log.debug("Successfully sent a close message for fetch session: {} to node: {}", sessionId, fetchTarget);
217	    }
218	
219	    public void handleCloseFetchSessionResponse(final Node fetchTarget,
220	                                                final FetchSessionHandler.FetchRequestData data,
221	                                                final Throwable t) {
222	        int sessionId = data.metadata().sessionId();
223	        log.debug("Unable to a close message for fetch session: {} to node: {}. " +
224	                "This may result in unnecessary fetch sessions at the broker.", sessionId, fetchTarget, t);
225	    }
226	
227	    /**
228	     * Creates a new {@link FetchRequest fetch request} in preparation for sending to the Kafka cluster.
229	     *
230	     * @param fetchTarget {@link Node} from which the fetch data will be requested
231	     * @param requestData {@link FetchSessionHandler.FetchRequestData} that represents the session data
232	     * @return {@link FetchRequest.Builder} that can be submitted to the broker
233	     */
234	    protected FetchRequest.Builder createFetchRequest(final Node fetchTarget,
235	                                                      final FetchSessionHandler.FetchRequestData requestData) {
236	        // Version 12 is the maximum version that could be used without topic IDs. See FetchRequest.json for schema
237	        // changelog.
238	        final short maxVersion = requestData.canUseTopicIds() ? ApiKeys.FETCH.latestVersion() : (short) 12;
239	
240	        final FetchRequest.Builder request = FetchRequest.Builder
241	                .forConsumer(maxVersion, fetchConfig.maxWaitMs, fetchConfig.minBytes, requestData.toSend())
242	                .isolationLevel(fetchConfig.isolationLevel)
243	                .setMaxBytes(fetchConfig.maxBytes)
244	                .metadata(requestData.metadata())
245	                .removed(requestData.toForget())
246	                .replaced(requestData.toReplace())
247	                .rackId(fetchConfig.clientRackId);
248	
249	        log.debug("Sending {} {} to broker {}", fetchConfig.isolationLevel, requestData, fetchTarget);
250	
251	        // We add the node to the set of nodes with pending fetch requests before adding the
252	        // listener because the future may have been fulfilled on another thread (e.g. during a
253	        // disconnection being handled by the heartbeat thread) which will mean the listener
254	        // will be invoked synchronously.
255	        log.debug("Adding pending request for node {}", fetchTarget);
256	        nodesWithPendingFetchRequests.add(fetchTarget.id());
257	
258	        return request;
259	    }
260	
261	    /**
262	     * Return the list of <em>fetchable</em> partitions, which are the set of partitions to which we are subscribed,
263	     * but <em>excluding</em> any partitions for which we still have buffered data. The idea is that since the user
264	     * has yet to process the data for the partition that has already been fetched, we should not go send for more data
265	     * until the previously-fetched data has been processed.
266	     *
267	     * @return {@link Set} of {@link TopicPartition topic partitions} for which we should fetch data
268	     */
269	    private Set<TopicPartition> fetchablePartitions() {
270	        // This is the set of partitions we have in our buffer
271	        Set<TopicPartition> buffered = fetchBuffer.bufferedPartitions();
272	
273	        // This is the test that returns true if the partition is *not* buffered
274	        Predicate<TopicPartition> isNotBuffered = tp -> !buffered.contains(tp);
275	
276	        // Return all partitions that are in an otherwise fetchable state *and* for which we don't already have some
277	        // messages sitting in our buffer.
278	        return new HashSet<>(subscriptions.fetchablePartitions(isNotBuffered));
279	    }
280	
281	    /**
282	     * Determine from which replica to read: the <i>preferred</i> or the <i>leader</i>. The preferred replica is used
283	     * iff:
284	     *
285	     * <ul>
286	     *     <li>A preferred replica was previously set</li>
287	     *     <li>We're still within the lease time for the preferred replica</li>
288	     *     <li>The replica is still online/available</li>
289	     * </ul>
290	     *
291	     * If any of the above are not met, the leader node is returned.
292	     *
293	     * @param partition {@link TopicPartition} for which we want to fetch data
294	     * @param leaderReplica {@link Node} for the leader of the given partition
295	     * @param currentTimeMs Current time in milliseconds; used to determine if we're within the optional lease window
296	     * @return Replica {@link Node node} from which to request the data
297	     * @see SubscriptionState#preferredReadReplica
298	     * @see SubscriptionState#updatePreferredReadReplica
299	     */
300	    Node selectReadReplica(final TopicPartition partition, final Node leaderReplica, final long currentTimeMs) {
301	        Optional<Integer> nodeId = subscriptions.preferredReadReplica(partition, currentTimeMs);
302	
303	        if (nodeId.isPresent()) {
304	            Optional<Node> node = nodeId.flatMap(id -> metadata.fetch().nodeIfOnline(partition, id));
305	            if (node.isPresent()) {
306	                return node.get();
307	            } else {
308	                log.trace("Not fetching from {} for partition {} since it is marked offline or is missing from our metadata," +
309	                        " using the leader instead.", nodeId, partition);
310	                // Note that this condition may happen due to stale metadata, so we clear preferred replica and
311	                // refresh metadata.
312	                requestMetadataUpdate(metadata, subscriptions, partition);
313	                return leaderReplica;
314	            }
315	        } else {
316	            return leaderReplica;
317	        }
318	    }
319	
320	    private Map<Node, FetchSessionHandler.FetchRequestData> prepareCloseFetchSessionRequests() {
321	        final Cluster cluster = metadata.fetch();
322	        Map<Node, FetchSessionHandler.Builder> fetchable = new LinkedHashMap<>();
323	
324	        try {
325	            sessionHandlers.forEach((fetchTargetNodeId, sessionHandler) -> {
326	                // set the session handler to notify close. This will set the next metadata request to send close message.
327	                sessionHandler.notifyClose();
328	
329	                // FetchTargetNode may not be available as it may have disconnected the connection. In such cases, we will
330	                // skip sending the close request.
331	                final Node fetchTarget = cluster.nodeById(fetchTargetNodeId);
332	
333	                if (fetchTarget == null || client.isUnavailable(fetchTarget)) {
334	                    log.debug("Skip sending close session request to broker {} since it is not reachable", fetchTarget);
335	                    return;
336	                }
337	
338	                fetchable.put(fetchTarget, sessionHandler.newBuilder());
339	            });
340	        } finally {
341	            sessionHandlers.clear();
342	        }
343	
344	        Map<Node, FetchSessionHandler.FetchRequestData> reqs = new LinkedHashMap<>();
345	        for (Map.Entry<Node, FetchSessionHandler.Builder> entry : fetchable.entrySet()) {
346	            reqs.put(entry.getKey(), entry.getValue().build());
347	        }
348	        return reqs;
349	    }
350	
351	    /**
352	     * Create fetch requests for all nodes for which we have assigned partitions
353	     * that have no existing requests in flight.
354	     */
355	    protected Map<Node, FetchSessionHandler.FetchRequestData> prepareFetchRequests() {
356	        // Update metrics in case there was an assignment change
357	        metricsManager.maybeUpdateAssignment(subscriptions);
358	
359	        Map<Node, FetchSessionHandler.Builder> fetchable = new LinkedHashMap<>();
360	        long currentTimeMs = time.milliseconds();
361	        Map<String, Uuid> topicIds = metadata.topicIds();
362	
363	        for (TopicPartition partition : fetchablePartitions()) {
364	            SubscriptionState.FetchPosition position = subscriptions.position(partition);
365	
366	            if (position == null)
367	                throw new IllegalStateException("Missing position for fetchable partition " + partition);
368	
369	            Optional<Node> leaderOpt = position.currentLeader.leader;
370	
371	            if (!leaderOpt.isPresent()) {
372	                log.debug("Requesting metadata update for partition {} since the position {} is missing the current leader node", partition, position);
373	                metadata.requestUpdate(false);
374	                continue;
375	            }
376	
377	            // Use the preferred read replica if set, otherwise the partition's leader
378	            Node node = selectReadReplica(partition, leaderOpt.get(), currentTimeMs);
379	
380	            if (client.isUnavailable(node)) {
381	                client.maybeThrowAuthFailure(node);
382	
383	                // If we try to send during the reconnect backoff window, then the request is just
384	                // going to be failed anyway before being sent, so skip sending the request for now
385	                log.trace("Skipping fetch for partition {} because node {} is awaiting reconnect backoff", partition, node);
386	            } else if (nodesWithPendingFetchRequests.contains(node.id())) {
387	                log.trace("Skipping fetch for partition {} because previous request to {} has not been processed", partition, node);
388	            } else {
389	                // if there is a leader and no in-flight requests, issue a new fetch
390	                FetchSessionHandler.Builder builder = fetchable.computeIfAbsent(node, k -> {
391	                    FetchSessionHandler fetchSessionHandler = sessionHandlers.computeIfAbsent(node.id(), n -> new FetchSessionHandler(logContext, n));
392	                    return fetchSessionHandler.newBuilder();
393	                });
394	                Uuid topicId = topicIds.getOrDefault(partition.topic(), Uuid.ZERO_UUID);
395	                FetchRequest.PartitionData partitionData = new FetchRequest.PartitionData(topicId,
396	                        position.offset,
397	                        FetchRequest.INVALID_LOG_START_OFFSET,
398	                        fetchConfig.fetchSize,
399	                        position.currentLeader.epoch,
400	                        Optional.empty());
401	                builder.add(partition, partitionData);
402	
403	                log.debug("Added {} fetch request for partition {} at position {} to node {}", fetchConfig.isolationLevel,
404	                        partition, position, node);
405	            }
406	        }
407	
408	        Map<Node, FetchSessionHandler.FetchRequestData> reqs = new LinkedHashMap<>();
409	        for (Map.Entry<Node, FetchSessionHandler.Builder> entry : fetchable.entrySet()) {
410	            reqs.put(entry.getKey(), entry.getValue().build());
411	        }
412	        return reqs;
413	    }
414	
415	    protected void maybeCloseFetchSessions(final Timer timer) {
416	        final List<RequestFuture<ClientResponse>> requestFutures = new ArrayList<>();
417	        Map<Node, FetchSessionHandler.FetchRequestData> fetchRequestMap = prepareCloseFetchSessionRequests();
418	
419	        for (Map.Entry<Node, FetchSessionHandler.FetchRequestData> entry : fetchRequestMap.entrySet()) {
420	            final Node fetchTarget = entry.getKey();
421	            final FetchSessionHandler.FetchRequestData data = entry.getValue();
422	            final FetchRequest.Builder request = createFetchRequest(fetchTarget, data);
423	            final RequestFuture<ClientResponse> responseFuture = client.send(fetchTarget, request);
424	
425	            responseFuture.addListener(new RequestFutureListener<ClientResponse>() {
426	                @Override
427	                public void onSuccess(ClientResponse value) {
428	                    handleCloseFetchSessionResponse(fetchTarget, data);
429	                }
430	
431	                @Override
432	                public void onFailure(RuntimeException e) {
433	                    handleCloseFetchSessionResponse(fetchTarget, data, e);
434	                }
435	            });
436	
437	            requestFutures.add(responseFuture);
438	        }
439	
440	        // Poll to ensure that request has been written to the socket. Wait until either the timer has expired or until
441	        // all requests have received a response.
442	        while (timer.notExpired() && !requestFutures.stream().allMatch(RequestFuture::isDone)) {
443	            client.poll(timer, null, true);
444	        }
445	
446	        if (!requestFutures.stream().allMatch(RequestFuture::isDone)) {
447	            // we ran out of time before completing all futures. It is ok since we don't want to block the shutdown
448	            // here.
449	            log.debug("All requests couldn't be sent in the specific timeout period {}ms. " +
450	                    "This may result in unnecessary fetch sessions at the broker. Consider increasing the timeout passed for " +
451	                    "KafkaConsumer.close(Duration timeout)", timer.timeoutMs());
452	        }
453	    }
454	
455	    // Visible for testing
456	    protected FetchSessionHandler sessionHandler(int node) {
457	        return sessionHandlers.get(node);
458	    }
459	
460	    /**
461	     * This method is called by {@link #close(Timer)} which is guarded by the {@link IdempotentCloser}) such as to only
462	     * be executed once the first time that any of the {@link #close()} methods are called. Subclasses can override
463	     * this method without the need for extra synchronization at the instance level.
464	     *
465	     * @param timer Timer to enforce time limit
466	     */
467	    // Visible for testing
468	    protected void closeInternal(Timer timer) {
469	        // we do not need to re-enable wake-ups since we are closing already
470	        client.disableWakeups();
471	        maybeCloseFetchSessions(timer);
472	        Utils.closeQuietly(fetchBuffer, "fetchBuffer");
473	        Utils.closeQuietly(decompressionBufferSupplier, "decompressionBufferSupplier");
474	    }
475	
476	    public void close(final Timer timer) {
477	        idempotentCloser.close(() -> {
478	            closeInternal(timer);
479	        });
480	    }
481	
482	    @Override
483	    public void close() {
484	        close(time.timer(0));
485	    }
486	}

