665	            log.debug("Not returning fetched records for partition {} since it is no longer assigned", tp);
666	        } else if (!subscriptions.isFetchable(tp)) {
667	            // this can happen when a partition is paused before fetched records are returned to the consumer's
668	            // poll call or if the offset is being reset
669	            log.debug("Not returning fetched records for assigned partition {} since it is no longer fetchable", tp);
670	        } else {
671	            SubscriptionState.FetchPosition position = subscriptions.position(tp);
672	
673	            if (position == null)
674	                throw new IllegalStateException("Missing position for fetchable partition " + tp);
675	
676	            if (nextInLineFetch.nextFetchOffset() == position.offset) {
677	                List<ConsumerRecord<K, V>> partRecords = nextInLineFetch.fetchRecords(fetchConfig, fetchConfig.maxPollRecords);
