720	     * Initialize a CompletedFetch object.
721	     */
722	    protected CompletedFetch initialize(final CompletedFetch completedFetch) {
723	        final TopicPartition tp = completedFetch.partition;
724	        final Errors error = Errors.forCode(completedFetch.partitionData.errorCode());
725	        boolean recordMetrics = true;
726	
727	        try {
728	            if (!subscriptions.hasValidPosition(tp)) {
