765	        final FetchResponseData.PartitionData partition = completedFetch.partitionData;
766	        log.trace("Preparing to read {} bytes of data for partition {} with offset {}",
767	                FetchResponse.recordsSize(partition), tp, position);
768	        Iterator<? extends RecordBatch> batches = FetchResponse.recordsOrFail(partition).batches().iterator();
769	
770	        if (!batches.hasNext() && FetchResponse.recordsSize(partition) > 0) {
771	            if (completedFetch.requestVersion < 3) {
772	                // Implement the pre KIP-74 behavior of throwing a RecordTooLargeException.
773	                Map<TopicPartition, Long> recordTooLargePartitions = Collections.singletonMap(tp, fetchOffset);
774	                throw new RecordTooLargeException("There are some messages at [Partition=Offset]: " +
775	                        recordTooLargePartitions + " whose size is larger than the fetch size " + fetchConfig.fetchSize +
776	                        " and hence cannot be returned. Please considering upgrading your broker to 0.10.1.0 or " +
777	                        "newer to avoid this issue. Alternately, increase the fetch size on the client (using " +
778	                        ConsumerConfig.MAX_PARTITION_FETCH_BYTES_CONFIG + ")",
779	                        recordTooLargePartitions);
780	            } else {
781	                // This should not happen with brokers that support FetchRequest/Response V3 or higher (i.e. KIP-74)
782	                throw new KafkaException("Failed to make progress reading messages at " + tp + "=" +
783	                        fetchOffset + ". Received a non-empty fetch response from the server, but no " +
784	                        "complete records were found.");
785	            }
786	        }
787	
788	        if (partition.highWatermark() >= 0) {
789	            log.trace("Updating high watermark for partition {} to {}", tp, partition.highWatermark());
790	            subscriptions.updateHighWatermark(tp, partition.highWatermark());
791	        }
792	
793	        if (partition.logStartOffset() >= 0) {
794	            log.trace("Updating log start offset for partition {} to {}", tp, partition.logStartOffset());
795	            subscriptions.updateLogStartOffset(tp, partition.logStartOffset());
796	        }
797	
798	        if (partition.lastStableOffset() >= 0) {
799	            log.trace("Updating last stable offset for partition {} to {}", tp, partition.lastStableOffset());
800	            subscriptions.updateLastStableOffset(tp, partition.lastStableOffset());
801	        }
802	
803	        if (FetchResponse.isPreferredReplica(partition)) {
804	            subscriptions.updatePreferredReadReplica(completedFetch.partition, partition.preferredReadReplica(), () -> {
805	                long expireTimeMs = time.milliseconds() + metadata.metadataExpireMs();
806	                log.debug("Updating preferred read replica for partition {} to {}, set to expire at {}",
807	                        tp, partition.preferredReadReplica(), expireTimeMs);
808	                return expireTimeMs;
809	            });
810	        }
811	
812	        completedFetch.setInitialized();
813	        return completedFetch;
814	    }
815	
816	    private void handleInitializeErrors(final CompletedFetch completedFetch, final Errors error) {
817	        final TopicPartition tp = completedFetch.partition;
818	        final long fetchOffset = completedFetch.nextFetchOffset();
819	
820	        if (error == Errors.NOT_LEADER_OR_FOLLOWER ||
821	                error == Errors.REPLICA_NOT_AVAILABLE ||
822	                error == Errors.KAFKA_STORAGE_ERROR ||
823	                error == Errors.FENCED_LEADER_EPOCH ||
824	                error == Errors.OFFSET_NOT_AVAILABLE) {
825	            log.debug("Error in fetch for partition {}: {}", tp, error.exceptionName());
826	            requestMetadataUpdate(metadata, subscriptions, tp);
827	        } else if (error == Errors.UNKNOWN_TOPIC_OR_PARTITION) {
828	            log.warn("Received unknown topic or partition error in fetch for partition {}", tp);
829	            requestMetadataUpdate(metadata, subscriptions, tp);
830	        } else if (error == Errors.UNKNOWN_TOPIC_ID) {
831	            log.warn("Received unknown topic ID error in fetch for partition {}", tp);
832	            requestMetadataUpdate(metadata, subscriptions, tp);
833	        } else if (error == Errors.INCONSISTENT_TOPIC_ID) {
834	            log.warn("Received inconsistent topic ID error in fetch for partition {}", tp);
835	            requestMetadataUpdate(metadata, subscriptions, tp);
836	        } else if (error == Errors.OFFSET_OUT_OF_RANGE) {
837	            Optional<Integer> clearedReplicaId = subscriptions.clearPreferredReadReplica(tp);
838	
839	            if (!clearedReplicaId.isPresent()) {
840	                // If there's no preferred replica to clear, we're fetching from the leader so handle this error normally
841	                SubscriptionState.FetchPosition position = subscriptions.position(tp);
842	
843	                if (position == null || fetchOffset != position.offset) {
844	                    log.debug("Discarding stale fetch response for partition {} since the fetched offset {} " +
845	                            "does not match the current offset {}", tp, fetchOffset, position);
846	                } else {
847	                    String errorMessage = "Fetch position " + position + " is out of range for partition " + tp;
848	
849	                    if (subscriptions.hasDefaultOffsetResetPolicy()) {
850	                        log.info("{}, resetting offset", errorMessage);
851	                        subscriptions.requestOffsetReset(tp);
852	                    } else {
853	                        log.info("{}, raising error to the application since no reset policy is configured", errorMessage);
854	                        throw new OffsetOutOfRangeException(errorMessage,
855	                                Collections.singletonMap(tp, position.offset));
856	                    }
857	                }
858	            } else {
859	                log.debug("Unset the preferred read replica {} for partition {} since we got {} when fetching {}",
860	                        clearedReplicaId.get(), tp, error, fetchOffset);
861	            }
862	        } else if (error == Errors.TOPIC_AUTHORIZATION_FAILED) {
863	            //we log the actual partition and not just the topic to help with ACL propagation issues in large clusters
864	            log.warn("Not authorized to read from partition {}.", tp);
865	            throw new TopicAuthorizationException(Collections.singleton(tp.topic()));
866	        } else if (error == Errors.UNKNOWN_LEADER_EPOCH) {
867	            log.debug("Received unknown leader epoch error in fetch for partition {}", tp);
868	        } else if (error == Errors.UNKNOWN_SERVER_ERROR) {
869	            log.warn("Unknown server error while fetching offset {} for topic-partition {}",
870	                    fetchOffset, tp);
871	        } else if (error == Errors.CORRUPT_MESSAGE) {
872	            throw new KafkaException("Encountered corrupt message when fetching offset "
873	                    + fetchOffset
874	                    + " for topic-partition "
875	                    + tp);
876	        } else {
877	            throw new IllegalStateException("Unexpected error code "
878	                    + error.code()
879	                    + " while fetching at offset "
880	                    + fetchOffset
881	                    + " from topic-partition " + tp);
882	        }
883	    }
