229	    /**
230	     * Set the fetch position to the committed position (if there is one) or reset it using the
231	     * offset reset policy the user has configured (if partitions require reset)
232	     *
233	     * @return true if the operation completed without timing out
234	     * @throws org.apache.kafka.common.errors.AuthenticationException if authentication fails. See the exception for more details
235	     * @throws NoOffsetForPartitionException                          If no offset is stored for a given partition and no offset reset policy is
236	     *                                                                defined
237	     */
238	    private boolean updateFetchPositionsIfNeeded(final Timer timer) {
239	        // Validate positions using the partition leader end offsets, to detect if any partition
240	        // has been truncated due to a leader change. This will trigger an OffsetForLeaderEpoch
241	        // request, retrieve the partition end offsets, and validate the current position against it.
242	        ValidatePositionsApplicationEvent validatePositionsEvent = new ValidatePositionsApplicationEvent();
243	        eventHandler.add(validatePositionsEvent);
244	
245	        // Reset positions using committed offsets retrieved from the group coordinator, for any
246	        // partitions which do not have a valid position and are not awaiting reset. This will
247	        // trigger an OffsetFetch request and update positions with the offsets retrieved. This
248	        // will only do a coordinator lookup if there are partitions which have missing
249	        // positions, so a consumer with manually assigned partitions can avoid a coordinator
250	        // dependence by always ensuring that assigned partitions have an initial position.
251	        if (isCommittedOffsetsManagementEnabled() && !refreshCommittedOffsetsIfNeeded(timer))
252	            return false;
253	
254	        // If there are partitions still needing a position and a reset policy is defined,
255	        // request reset using the default policy. If no reset strategy is defined and there
256	        // are partitions with a missing position, then we will raise a NoOffsetForPartitionException exception.
257	        subscriptions.resetInitializingPositions();
258	
259	        // Reset positions using partition offsets retrieved from the leader, for any partitions
260	        // which are awaiting reset. This will trigger a ListOffset request, retrieve the
261	        // partition offsets according to the strategy (ex. earliest, latest), and update the
262	        // positions.
263	        ResetPositionsApplicationEvent resetPositionsEvent = new ResetPositionsApplicationEvent();
264	        eventHandler.add(resetPositionsEvent);
265	        return true;
266	    }
