451	        requireNonNull(timestampsToSearch, "Timestamps to search cannot be null");
452	        for (Map.Entry<TopicPartition, Long> entry : timestampsToSearch.entrySet()) {
453	            // Exclude the earliest and latest offset here so the timestamp in the returned
454	            // OffsetAndTimestamp is always positive.
455	            if (entry.getValue() < 0)
456	                throw new IllegalArgumentException("The target time for partition " + entry.getKey() + " is " +
457	                        entry.getValue() + ". The target time cannot be negative.");
458	        }
459	
460	        if (timestampsToSearch.isEmpty()) {
461	            return Collections.emptyMap();
462	        }
463	        final ListOffsetsApplicationEvent listOffsetsEvent = new ListOffsetsApplicationEvent(
464	                timestampsToSearch,
465	                true);
466	
467	        // If timeout is set to zero return empty immediately; otherwise try to get the results
468	        // and throw timeout exception if it cannot complete in time.
469	        if (timeout.toMillis() == 0L)
470	            return listOffsetsEvent.emptyResult();
471	
472	        return eventHandler.addAndGet(listOffsetsEvent, time.timer(timeout));
473	    }
