        Objects.requireNonNull(event, "ApplicationEvent provided to add must be non-null");
        log.trace("Enqueued event: {}", event);
        applicationEventQueue.add(event);
        wakeupNetworkThread();
    }

    /**
     * Wakeup the network thread, which is useful for ensuring that the thread processes events or polls the network
     * as soon as possible.
