    public void testPollOnCloseWithoutSessionsHasNoRequests() {
        assertTrue(fetchRequestManager.pollOnClose().unsentRequests.isEmpty());
    }

    @Test
    public void testPollOnCloseClosesFetchSessions() {
        assignAndSeek(tp0);

